#include <stdio.h>
#include <stdlib.h>

#define MAX(a,b) ((a) > (b) ? (a) : (b))

#define MAX_SIZE 1000
#define MAX_VAL 1000

int cmp(const void* a, const void* b) {
    return (*(int*) a) - (*(int*) b);
}

int main() {
    // 输入数组
    int nums[MAX_SIZE] = {0};
    int nums_size = 0;

    while(scanf("%d", &nums[nums_size++])) {
        if(getchar() != ' ') break;
    }

    // 每个数的出现次数
    int count[MAX_VAL] = {0};
    // 最大出现次数
    int maxCount = 0;
    for(int i=0; i<nums_size; i++) {
        count[nums[i]]++;
        maxCount = MAX(maxCount, count[nums[i]]);
    }

    // 众数数组
    int mode[MAX_SIZE] = {0};
    int mode_size = 0;

    for(int i=0; i<MAX_VAL; i++) {
        // 如果该数的出现次数是最大出现次数，则是众数
        if(count[i] == maxCount) {
            mode[mode_size++] = i;
        }
    }

    // 众数数组升序
    qsort(mode, mode_size, sizeof(int), cmp);

    // 取众数数组的中位数
    int mid = mode_size / 2;

    if(mode_size % 2 == 0) {
        printf("%d\n", (mode[mid] + mode[mid - 1]) / 2);
    } else {
        printf("%d\n", mode[mid]);
    }

    return 0;
}
